# v623: the materials forge (the owner's art in docs/art/mat, tinted per rarity), the wheel made simple and clean, and the bag opening the
# items on their own page with the right count. See p623_ui.js.
import sys, re
P = sys.argv[1] if len(sys.argv) > 1 else 'docs/index.html'
s = open(P, encoding='utf-8').read()
def rep(a, b, n=1):
    global s
    c = s.count(a); assert c == n, (c, a[:90]); s = s.replace(a, b)
js = open('tools/patches/p623_ui.js', encoding='utf-8').read()
css = ('.fsmat-alloy{background-image:url(art/mat/alloy.webp)!important}.fsmat-circuit{background-image:url(art/mat/circuit.webp)!important}.fsmat-crystal{background-image:url(art/mat/crystal.webp)!important}.fsmat-bio{background-image:url(art/mat/bio.webp)!important}.fsmat-cube{background-image:url(art/mat/cube.webp)!important}.fsmat-void{background-image:url(art/mat/void.webp)!important}.fsmi{background-color:transparent!important;background-size:contain!important}'
  '.fgtabs{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:6px;margin:4px 0 8px}.fgtabs button{display:flex;flex-direction:column;align-items:center;gap:2px;padding:6px 2px 4px;border-radius:12px;border:1px solid rgba(122,196,255,.18);background:rgba(10,24,40,.7);color:var(--muted);cursor:pointer}.fgtabs button .fsmi{width:34px;height:34px;margin:0;box-shadow:none}.fgtabs button small{font-size:10.5px}.fgtabs button.on{border-color:#7af4ff;background:rgba(122,244,255,.12);color:#e9fdff;box-shadow:0 0 12px rgba(122,244,255,.3)}'
  '.fgtabs,.fgcard,.fsmore{flex-shrink:0}.fgcard{position:relative;overflow:hidden;border-radius:16px;border:1px solid rgba(122,196,255,.25);padding:12px 10px;background:#060c18}.fgbg{position:absolute;inset:0;background-size:cover;background-position:center;opacity:.42;filter:saturate(1.1);pointer-events:none}.fgcard::before{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(4,8,18,.55),rgba(4,8,18,.25) 40%,rgba(4,8,18,.85));pointer-events:none}.fgcard>*{position:relative}'
  '.fghd{display:flex;align-items:center;gap:10px}.fghd>div{flex:1;min-width:0;display:flex;flex-direction:column}.fghd b{font-size:17px;font-family:var(--f-display)}.fghd small{font-size:11.5px;color:var(--muted)}.fghd .fsmi.lg{width:40px;height:40px;margin:0;box-shadow:none}'
  '.fggems{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:12px 0 6px}.fgem{position:relative;display:flex;flex-direction:column;align-items:center;gap:1px;padding:8px 4px 6px;border-radius:14px;border:1px solid color-mix(in srgb,var(--c) 35%,transparent);background:radial-gradient(circle at 50% 38%,color-mix(in srgb,var(--c) 22%,transparent),rgba(5,10,22,.75) 70%);color:#e9f2ff;cursor:pointer;overflow:visible}'
  '.fgem.none{opacity:.45;filter:grayscale(.6)}.fgem .fgring{position:absolute;left:50%;top:8px;width:74px;height:74px;margin-left:-37px;border-radius:50%;background:conic-gradient(var(--c) calc(var(--p)*360deg),rgba(255,255,255,.08) 0);-webkit-mask:radial-gradient(circle,transparent 33px,#000 34px);mask:radial-gradient(circle,transparent 33px,#000 34px);opacity:.9}'
  '.fgimg{width:66px;height:66px;margin:4px 0 2px;object-fit:contain;filter:drop-shadow(0 0 6px color-mix(in srgb,var(--c) 70%,transparent));pointer-events:none}.fgem b{font-size:18px;font-family:var(--f-display);line-height:1.1}.fgem small{font-size:11px;color:var(--c);font-weight:700}.fgem em{font-style:normal;font-size:9.5px;opacity:.6}'
  '.fgem.ready{border-color:var(--c);box-shadow:0 0 16px color-mix(in srgb,var(--c) 55%,transparent);animation:fgrdy 1.6s ease-in-out infinite}.fgem.ready .fgimg{animation:fgbob 1.6s ease-in-out infinite}@keyframes fgrdy{50%{box-shadow:0 0 26px color-mix(in srgb,var(--c) 85%,transparent)}}@keyframes fgbob{50%{transform:translateY(-3px) scale(1.05)}}'
  '.fgem.myth{background:radial-gradient(circle at 50% 38%,color-mix(in srgb,var(--c) 32%,transparent),rgba(5,10,22,.75) 72%)}.fgem.pop .fgimg{animation:fgpop .95s cubic-bezier(.2,1.7,.4,1)}.fgem.pop::after{content:"";position:absolute;left:50%;top:42px;width:20px;height:20px;margin:-10px;border-radius:50%;border:3px solid var(--c);animation:fgburst .9s ease-out forwards;pointer-events:none}.fgem.pop.big::after{animation-duration:1.4s;border-width:5px}'
  '@keyframes fgpop{0%{transform:scale(.2);filter:brightness(3)}60%{transform:scale(1.25)}100%{transform:scale(1)}}@keyframes fgburst{0%{transform:scale(.5);opacity:1}100%{transform:scale(7);opacity:0}}'
  '.fgin{position:absolute;inset:0;pointer-events:none}.fgin s{position:absolute;left:50%;top:42px;width:9px;height:9px;margin:-4.5px;border-radius:50%;background:var(--c);box-shadow:0 0 10px var(--c);animation:fgin .55s ease-in forwards}.fgin s:nth-child(1){--x:-70px;--y:-40px}.fgin s:nth-child(2){--x:70px;--y:-40px}.fgin s:nth-child(3){--x:-60px;--y:50px}.fgin s:nth-child(4){--x:60px;--y:50px}.fgin s:nth-child(5){--x:0px;--y:-70px}@keyframes fgin{0%{transform:translate(var(--x),var(--y));opacity:0}30%{opacity:1}100%{transform:translate(0,0);opacity:0}}'
  '.fgflash{position:fixed;inset:0;z-index:99;pointer-events:none;background:radial-gradient(circle at 50% 45%,rgba(255,79,106,.75),rgba(255,180,120,.25) 40%,transparent 70%);animation:fgflash 1.3s ease-out forwards}@keyframes fgflash{0%{opacity:0}15%{opacity:1}100%{opacity:0}}'
  '.fgnext{text-align:center;font-size:13px;margin:6px 0 8px}.fgall{margin-top:2px}.fguse{text-align:center;font-size:11px;margin:8px 0 0}.fsmore{margin-top:10px;border:1px solid rgba(122,196,255,.18);border-radius:12px;padding:6px 10px}.fsmore>summary{cursor:pointer;color:#7af4ff;font-size:13px;padding:4px 0}'
  '.gwz .gwx>b.gwst{background:none;-webkit-background-clip:border-box;background-clip:border-box;color:#e9fdff;filter:none;font-size:17px;font-style:normal;font-weight:700;letter-spacing:.01em;text-shadow:0 0 10px rgba(122,244,255,.55)}.gwbuy2{display:flex;gap:8px;justify-content:center;align-items:center;margin:6px 0 2px;width:100%}'
  '.gwgo{flex:0 1 230px;font-size:17px;letter-spacing:.16em;padding:12px 0;background:linear-gradient(180deg,#ffe08a,#ffb347)!important;color:#2a1600!important;border:0!important;box-shadow:0 0 18px rgba(255,190,80,.55);border-radius:14px;font-weight:800}.gwgo[disabled]{filter:grayscale(.7);opacity:.55}.gwz.ready .gwgo{animation:gwgo 1.6s ease-in-out infinite}@keyframes gwgo{50%{box-shadow:0 0 30px rgba(255,200,90,.95)}}.gw5{white-space:nowrap}.gwcap{font-size:11px;opacity:.65}'
  '.gwrow{display:flex;align-items:center;justify-content:center;gap:14px;background:rgba(255,255,255,.03);border:1px solid rgba(255,214,110,.14);border-radius:999px;padding:6px 14px;cursor:pointer;color:inherit;margin:6px auto 0}.gwrow.on{border-color:rgba(255,214,110,.45)}.gwrow i{font-style:normal}'
  '.gwring{display:block;width:20px;height:20px;border-radius:50%;background:conic-gradient(#ff6ad5 calc(var(--p)*360deg),rgba(255,255,255,.14) 0);-webkit-mask:radial-gradient(circle,transparent 5px,#000 6px);mask:radial-gradient(circle,transparent 5px,#000 6px)}'
  '.gwlink{background:none;border:0;color:#7af4ff;font-size:12px;cursor:pointer;padding:6px;text-decoration:underline;text-underline-offset:3px}.gwodds{display:grid;gap:3px;width:100%;margin-top:2px;text-align:left}.gwor{display:grid;grid-template-columns:22px minmax(0,1fr) auto;gap:8px;align-items:center;padding:5px 9px;border-radius:8px;background:rgba(255,255,255,.04);font-size:12px}.gwor b{color:var(--c);text-shadow:0 0 6px var(--c)}.gwor em{font-style:normal;opacity:.75}.gwor.jack{background:rgba(255,106,213,.1)}.gwor.won,.gwor.force{outline:1px solid var(--c)}'
  '.gwstage{position:relative}.gwpot2,.gwlh2{position:absolute;z-index:2;top:3%;font-size:11.5px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap}.gwpot2{left:1%;background:rgba(255,106,213,.18);border:1px solid #ff6ad5;color:#ffb0f0}.gwlh2{right:1%;background:linear-gradient(90deg,#ff6ad5,#ffcf5a);color:#1a0f20;animation:gwlh 1.6s ease-in-out infinite}.gwz.lucky{border-color:rgba(255,207,90,.7)}'
  '.invhd .chapter{color:#ffcf5a}\n')
i = s.index('</style>', s.index('#celeb{position:fixed')); s = s[:i] + css + s[i:]
# the new wheel replaces the old one, the forge and the bag helpers go beside it
a = s.index('function wheelHTML(T) {'); b = s.index('\nfunction wheelPull', a); s = s[:a] + js.rstrip() + s[b:]
# the inventory grid as its own function, for the shop tab and the bag's page
m = re.search(r'  else if \(cat === "inv"\) body = (inv\.length \? .*?Items you buy, and spoils from pirate raids, land here\.</p>\';)\n', s, re.S); assert m
expr = m.group(1)[:-1]
s = s.replace(m.group(0), '  else if (cat === "inv") body = invGridHTML();\n', 1)
fn = ('function invGridHTML() { const it = S.items || {}, inv = Object.keys(it).filter(k => it[k] > 0 && SHOP[k]); const art = (k, s) => { const a = shopArtOf(k); return a ? `<span class="sart" style="background-image:url(${a})"></span>` : `<span class="sart g" style="--tc:${s.col || "#55d6e8"}">${s.ic.length === 1 && "mcg".includes(s.ic) ? RI[s.ic] : s.ic}</span>`; };\n'
      '  return ' + expr + '; }\n'
      'function shInv() { return `<div class="hd invhd"><div style="flex:1;min-width:0"><div class="chapter">Your items</div><h2>Inventory · ${fmt(invCount())}</h2><p class="note">Boosters, crates, accelerators and spoils. Tap Use to use one.</p></div><button class="x" data-act="close" aria-label="Close">✕</button></div>${invGridHTML()}<button class="btn ghost wide" style="margin-top:12px" data-act="openShop">Get more in the Void Shop ›</button>`; }\n')
a = s.index('function shShop() {'); s = s[:a] + fn + s[a:]
rep('archives: shArch, depot: shDepot,', 'archives: shArch, depot: shDepot, inv: shInv,')
rep('const n = Object.values(S.items || {}).filter(v => v > 0).length;', 'const n = invCount();')
rep('invOpen: () => { closeSheet(); openSheet({ type: "shop", cat: "inv", noIntro: 1 }); }', 'invOpen: () => { closeSheet(); openSheet({ type: "inv", noIntro: 1 }); }, whlPull: () => wheelPull(), whlInfo: () => { G.whlInfo = !G.whlInfo; renderSheet(); }, whlOdds: () => { G.whlOdds = !G.whlOdds; renderSheet(); },\n'
    '  fsMatTab: d => { if (FS_MATS[d.v]) { sheet.fm = d.v; renderSheet(); } }, fsCombAll: d => { const f = fsOf(), m = d.v; let made = 0, top = null; for (let t = 1; t <= 5; t++) { const k = fsMatKey(m, t); while ((f.mats[k] || 0) >= 5 && pay(fsCombCost(t))) { f.mats[k] -= 5; if (!f.mats[k]) delete f.mats[k]; const k2 = fsMatKey(m, t + 1); f.mats[k2] = (f.mats[k2] || 0) + 1; made++; top = [k2, t + 1]; } }\n'
    '    if (!made) return toast("Nothing to fuse yet, or not enough resources.", "warn"); fsBump(); fsFuseFx(top[0], top[1]); toast(`Fused ${made} time${made > 1 ? "s" : ""}. Best: ${FS_TIER[top[1]][0]} ${FS_MATS[m][0]}.`, "win"); renderSheet(); }')
rep('f.mats[k] -= 5; if (!f.mats[k]) delete f.mats[k]; const k2 = k.slice(0, -1) + (t + 1); f.mats[k2] = (f.mats[k2] || 0) + 1; fsBump(); renderSheet(); },',
    'f.mats[k] -= 5; if (!f.mats[k]) delete f.mats[k]; const k2 = k.slice(0, -1) + (t + 1); f.mats[k2] = (f.mats[k2] || 0) + 1; fsBump(); fsFuseFx(k2, t + 1); renderSheet(); }, /* v623 the fusion moment */')
# the materials page: the forge, with the converter and auto-combine folded under it
m = re.search(r'    body = conv \+ fsAutoCombHTML\(\) \+ `<p class="note">Combine five of a tier.*?\.join\(""\); \}\n  return head \+ tabs \+ body;', s, re.S); assert m
s = s.replace(m.group(0), '    body = fsForgeHTML(f, FS_MATS[sheet.fm] ? sheet.fm : "alloy") + `<p class="note" style="text-align:center">Today\'s drops: ${fmt((f.day && f.day.d === utcDay() ? f.day.n : 0))} (after ${FS_DAY_CAP} a day, each further drop is less likely).</p><details class="fsmore"><summary>Converter and auto-combine</summary>${conv}${fsAutoCombHTML()}</details>`; } /* v623 */\n  return head + tabs + body;', 1)
s2 = re.sub(r"GAME_V = 622\b", "GAME_V = 623", s); assert s2 != s; s = s2
open(P, 'w', encoding='utf-8').write(s); print('ok')
